  g = `Kolaborasi Bundle`,
  _ = `Pilihan: Anda boleh memilih untuk menjemput pembangun lain memasukkan permainan mereka ke dalam bundle anda. Sebagai pemilik bundle, anda bertanggungjawab untuk membuat pelarasan dengan pembangun lain. Selain itu, sebagai pemilik, hanya anda yang boleh menerbitkan bundle tersebut di Steam Store. Pihak yang dijemput boleh memilih permainan/pakej yang ingin dimasukkan. Setiap kali pakej ditambah ke dalam bundle atau peratusan diskaun berubah, semua kolaborator mesti meluluskan penyertaan permainan mereka untuk dimasukkan ke dalam bundle sebelum boleh diterbitkan.`,
