  w = `Halaman Acara Promosi Jualan`,
  T = `Di sini anda akan menemui halaman jualan di Steam yang menampilkan satu atau lebih permainan di bawah pengurusan anda. Dalam sesetengah keadaan, halaman ini disusun oleh penganjur acara dan kadangkala oleh Valve sebagai sebahagian daripada acara promosi yang dianjurkan.`,
