  at = `Acara jualan perlu dicipta pada laman utama pencipta (iaitu halaman Pembangun / Penerbit / Francais). Cari nama laman utama pencipta di bawah:`,
  ot = `Taip sama ada nama kumpulan yang dikaitkan dengan laman utama pencipta atau masukkan URL gedung jika ini adalah untuk kurator atau kumpulan komuniti yang baru dicipta.`,
  st = `1. Pencipta Pilihan untuk menganjurkan Acara Jualan:`,
  ct = `Kosongkan Pencipta dan Cari semula untuk laman utama pencipta yang lain`,
  lt = `2. Sahkan bahawa laman utama pencipta telah Mendayakan Acara Rakan Kongsi:`,
  ut = `Laman utama pencipta ini perlu menyertai beta Acara Rakan Kongsi untuk menggunakan ciri jualan. Tindakan ini tidak boleh dipulihkan. Tindakan ini akan menukar editor yang digunakan untuk menyiarkan pengumuman dan akan menghalang mereka daripada mencipta pengumuman yang dipautkan. %1$s`,
  dt = `3. Masukkan maklumat minimum yang diperlukan:`,
  ft = `Nama Acara Deskriptif`,
  pt = `Ini ialah nama acara panjang yang dipaparkan kepada pengguna. Ia boleh termasuk nama rakan kongsi dan tarikh acara`,
