  ko = `Tarikh keluaran permainan anda ditetapkan pada tarikh yang telah berlalu, sebab itulah permainan anda tidak layak secara automatik. Jika tarikh keluaran anda ditetapkan pada tarikh yang telah berlalu, tetapi permainan anda masih belum dikeluarkan, anda boleh membuat rayuan untuk disertakan dengan mengklik butang di bawah.`,
