  xm = `Salah satu aplikasi anda tiada rating umur Jerman. Bermula 15 November 2024, Steam tidak akan memaparkan tajuk tersebut kepada pelanggan yang melayari Steam Store di Jerman lagi. Untuk memastikan permainan anda tersedia untuk jualan di Jerman, sila lengkapkan dan terbitkan soal selidik kandungan terbina dalam Steam.`,
