  h_ = `Antipenipuan`,
  g_ = `Jika permainan anda memasang antipenipuan mod kernel pada klien, anda perlu mendedahkan perkara tersebut kepada pengguna di sini. Jika anda mempunyai penyelesaian antipenipuan sendiri atau penyelesaian anda tidak disenaraikan di bawah, sila pilih "lain-lain" dan masukkan maklumat anda sendiri.`,
  __ = `Jika permainan anda mengandungi antipenipuan berasaskan klien atau pelayan yang bukan berasaskan kernel, medan ini adalah pilihan. Namun, kami secara umumnya berpendapat bahawa mana-mana permainan yang menggunakan teknologi antipenipuan akan menerima manfaat dengan memberitahu pemain.`,
