  b_ = `Penyelesaian antipenipuan ini melibatkan pemasangan atau pengubahsuaian fail pada peringkat kernel OS.`,
  x_ = `Penyelesaian antipenipuan ini tidak mengubah suai fail pada peringkat kernel OS.`,
  S_ = `Sila pilih jika penyelesaian antipenipuan anda memasang fail pada peringkat kernel OS untuk mana-mana mod permainan anda.`,
  C_ = `Nyahpasang Sepenuhnya`,
  w_ = `Pilih pilihan ini hanya jika anda boleh mengesahkan bahawa semua fail berkaitan antipenipuan yang dipasang oleh permainan anda akan dialih keluar daripada cakera apabila permainan dinyahpasang.`,
  T_ = `Perlindungan Boot Diperlukan`,
  E_ = `Jika permainan anda memerlukan Secure Boot, TPM atau langkah perlindungan boot lain didayakan dalam mana-mana mod permainan, sila pilih kombinasi yang diperlukan.`,
