  H_ = `Semua Platform`,
  U_ = `Windows`,
  W_ = `Tandakan kotak ini jika tiada komponen edaran semula diperlukan`,
  G_ = `Unreal Engine biasanya memerlukan Visual C++. Sesetengah permainan UE mungkin juga memerlukan DirectX`,
  K_ = `Edisi Kumpulan`,
  q_ = `Terangkan Edisi Anda...`,
  J_ = `Antaramuka ini membolehkan anda menyediakan imej yang menerangkan perbezaan antara edisi permainan anda (cth., Standard vs. Deluxe vs. Game Of The Year, dll.). Edisi akan dikumpulkan bersama permainan asas di bahagian atas pilihan pembelian dan disusun daripada harga terendah ke tertinggi pada halaman gedung. Untuk maklumat lanjut, sila lihat <1>Dokumentasi Urus Edisi</1>.`,
