  $S = `Diskaun yang dijadualkan akan menyebabkan harga pakej ini jatuh di bawah harga minimum yang diperlukan dalam satu atau lebih mata wang. Oleh itu, pakej ini tidak boleh dibeli di negara tersebut. Untuk memastikan pakej ini boleh dibeli di mana-mana sahaja, anda perlu memasukkan peratus diskaun yang lebih rendah daripada %1$s% bagi pakej ini.`,
