  RP = `Acara Diskaun Rasmi`,
  zP = `Diskaun Dirancang`,
  BP = `Langkah %1$s`,
  VP = `Sokongan INPUT UMUM`,
  HP = `Bagi membantu anda menerangkan tahap sokongan alat kawalan permainan anda kepada pemain dengan sebaiknya, kami menyediakan wizard ringkas dengan beberapa soalan pendek. Sila lengkapkan wizard ini berdasarkan pengetahuan terbaik anda, supaya Steam boleh menghubungkan pemain dengan permainan yang berfungsi dengan baik pada peranti yang mereka miliki.`,
  UP = `Sila ambil maklum bahawa sebarang peranti VR, termasuk peranti input yang disokong oleh permainan anda perlu diterangkan dalam keperluan sistem. Sokongan alat kawalan yang diterangkan di sini merujuk kepada sokongan mod desktop atau Big Picture anda.`,
  WP = `Apakah jenis peranti yang boleh digunakan untuk bermain permainan anda dengan selesa?`,
  GP = `Tetikus dan papan kekunci sahaja`,
  KP = `Tetikus dan papan kekunci, serta gamepad`,
  qP = `Tetikus dan papan kekunci, tetapi gamepad lebih disukai`,
  JP = `Gamepad Diperlukan; Tiada sokongan untuk tetikus dan papan kekunci`,
  YP = `Ya, permainan saya memenuhi kriteria di atas untuk sokongan penuh`,
  XP = `Tidak, permainan saya tidak memenuhi semua kriteria di atas`,
  ZP = `Alat Kawalan DualShock (USB)`,
  QP = `Alat Kawalan DualShock (USB + Bluetooth)`,
  $P = `Alat Kawalan DualSense (USB)`,
  eF = `Alat Kawalan DualSense (USB + Bluetooth)`,
  tF = `Tidak, permainan saya tidak menyokong mana-mana Alat Kawalan PlayStation`,
  nF = `Ya, permainan saya mempunyai integrasi penuh API Input Steam`,
  rF = `Tidak, permainan saya tidak menggunakan API Input Steam`,
  iF = `Sokongan Alat Kawalan Xbox`,
  aF = `Jika permainan anda mempunyai sokongan penuh Alat Kawalan Xbox, pemain sepatutnya boleh melancarkan, mengkonfigurasi, bermain dan keluar daripada permainan anda tanpa akses kepada papan kekunci. Untuk menunjukkan dengan tepat bahawa permainan anda mempunyai sokongan penuh Alat Kawalan Xbox, permainan anda perlu boleh melakukan perkara berikut:`,
  oF = `Pemain mesti boleh melakukan semua dalam permainan hanya dengan menggunakan alat kawalan. Ini termasuk melepasi sebarang pelancar prapermainan, bermain permainan, berinteraksi dengan menu, menukar tetapan dan keluar daripada permainan.`,
  sF = `Apabila alat kawalan terputus sambungan, permainan mesti dijeda melainkan ia permainan berbilang pemain.`,
  cF = `Mana-mana arahan untuk memasukkan teks mesti membuka papan kekunci maya pada skrin.`,
  lF = `Jika permainan anda menyokong mod berbilang pemain setempat, mod tersebut mesti berfungsi dengan beberapa alat kawalan.`,
  uF = `Adakah permainan anda memenuhi kriteria di atas untuk sokongan penuh Alat Kawalan Xbox?`,
  dF = `Sokongan Alat Kawalan PlayStation`,
  fF = `Jika permainan anda menyokong satu atau lebih model Alat Kawalan PlayStation yang disenaraikan di bawah, secara amnya peranti tersebut sepatutnya boleh digunakan untuk melakukan semua dalam permainan yang boleh dilakukan dengan alat kawalan Xbox. Selain itu, permainan anda mesti memenuhi perkara berikut untuk dianggap menyokong alat kawalan PlayStation:`,
  pF = `Paparkan glif (ikon) yang betul pada skrin apabila meminta pengguna menekan butang tertentu pada alat kawalan.`,
  mF = `Bermain permainan, berinteraksi dengan menu, menukar tetapan, keluar.`,
  hF = `<1>Nota USB/Bluetooth:</1> Bagi alat kawalan PlayStation pada PC, sambungan USB biasanya berfungsi dengan baik, tetapi mungkin tidak mempunyai tahap sokongan yang sama apabila disambungkan melalui Bluetooth. Sila sahkan dengan pasukan teknikal anda bahawa permainan ini memang berfungsi dengan Bluetooth sebelum memilih pilihan di bawah.`,
  gF = `<1>Ya</1>, permainan saya menyokong: (pilih semua yang berkenaan)`,
  _F = `Integrasi API Steam Input`,
  vF = `Jika permainan anda telah diintegrasikan sepenuhnya dengan API Input Steam, ia sepatutnya berfungsi sepenuhnya dengan hampir mana-mana daripada 200+ model alat kawalan yang disambungkan oleh pemain, termasuk model masa hadapan. Untuk menyatakan dengan tepat bahawa permainan anda mempunyai sokongan ini, permainan anda perlu sekurang-kurangnya melakukan perkara berikut:`,
  yF = `Laksanakan tindakan API Input Steam dan dapatkan asal tindakan yang berkaitan untuk memaparkan glif alat kawalan yang betul dalam permainan bagi model alat kawalan utama.`,
  bF = `Jeda secara automatik jika alat kawalan terputus sambungan.`,
  xF = `Pemain mesti boleh memetakan semula butang pada alat kawalan yang digunakan melalui pengkonfigurasi Steam.`,
  SF = `Jika anda mempunyai keraguan, sila tanya pasukan teknikal anda sama ada mereka menggunakan API Input Steam.`,
  CF = `Adakah permainan anda menggunakan API Input Steam sepenuhnya seperti yang diterangkan di atas?`,
  wF = `Wizard Sokongan Alat Kawalan`,
  TF = `Ringkasan`,
  EF = `Berdasarkan maklumat yang anda berikan tentang sokongan alat kawalan anda, Steam akan memaparkan pecahan berikut kepada pelanggan:`,
  DF = `Berdasarkan maklumat yang anda berikan tentang sokongan alat kawalan, Steam tidak akan memaparkan sebarang peranti gamepad sebagai disokong.`,
