  qF = `Minta Kunci Playtest`,
  JF = `Gunakan borang ini untuk meminta kunci Steam bagi pakej playtest anda. Semua permintaan kunci Steam akan disemak oleh Valve secara kes demi kes, biasanya dalam tempoh 48-72 jam.`,
  YF = `Sila gunakan kotak di bawah untuk memberitahu kami juga tentang tujuan penggunaan kunci ini supaya kami boleh membantu memastikan anda meminta kuantiti yang sesuai dengan keperluan anda.`,
