  NI = `Lawatan Kedai semasa Fest`,
  PI = `Semua lawatan ke laman gedung permainan anda sepanjang tempoh acara tersebut, dari mana-mana sahaja di Steam atau web. Hanya dipaparkan untuk permainan yang membenarkan anda melihat trafik pemasaran.`,
