  KI = `Permainan Anda:`,
  qI = `Tiada laman utama pencipta yang ditetapkan untuk aplikasi anda. Sila semak dokumentasi laman utama pencipta untuk <1>halaman pembangun / halaman penerbit</1> atau untuk <2>halaman francais</2> untuk menetapkannya bagi Aplikasi anda`,
