  hL = `Kapsul Tidak Tersedia`,
  gL = `<Include from all sources>`,
  _L = `Sertakan semua permainan daripada kesemua laman utama pencipta (pembangun/penerbit/francais) yang berkaitan dengan permainan ini. Menonjol secara manual membenarkan pemilihan laman utama pencipta tertentu untuk diserlahkan. Penonjolan berasaskan algoritma akan memilih perlawanan pertama Pencipta dalam susunan Francais, Pembangun dan Penerbit untuk paparan.`,
  vL = `Kebergantungan DLC`,
  yL = `Adakah DLC ini memerlukan item DLC lain untuk berfungsi? Pilih item DLC yang diperlukan untuk dipaparkan mengikut keperluan. Kedai akan memaparkan kebergantungan ini secara automatik, bersama-sama dengan pilihan untuk membeli semua item yang saling bergantung bersama.`,
