  EL = `Gambaran`,
  DL = `Reka Bentuk`,
  OL = `Mengeluarkan`,
  kL = `Penerangan Pelan Hala Tuju Pas Musim`,
  AL = `Pas Musim ialah item DLC yang boleh dibeli dengan janji kandungan masa hadapan yang akan dihantar kepada pelanggan. Kandungan ini boleh diberikan sebagai keluaran DLC berasingan atau sebagai kandungan tambahan yang dibuka dalam permainan asas.`,
  jL = `Untuk memenuhi komitmen ini, pembangun perlu menerangkan setiap tarikh penghantaran kandungan utama dan kandungannya kepada pemain dengan memasukkan setiap tarikh dan kandungan di bawah.`,
  ML = `Gunakan bahagian umum "Tentang DLC Ini" di atas untuk menerangkan pas musim secara keseluruhan dan gunakan tarikh penghantaran kandungan di bawah untuk menjelaskan setiap keluaran kandungan secara individu.`,
  NL = `Apabila anda sudah bersedia untuk memberitahu pemain bahawa kandungan dalam pas musim telah dikeluarkan, gunakan pilihan "Tandakan sebagai Dikeluarkan" di bawah dan ikuti arahan yang diberikan. Sila rujuk <1>Dokumentasi Keluaran Pas Musim</1> untuk butiran lanjut.`,
  PL = `Cipta Keluaran Kandungan Baharu`,
  FL = `Keluaran Kandungan ialah hasil penghantaran khusus yang boleh difahami oleh pelanggan, dengan tarikh jangkaan penghantaran.`,
  IL = `Cipta Keluaran Kandungan Baharu`,
  LL = `Sila terangkan keluaran kandungan pas musim anda kepada pemain.`,
  RL = `Penerangan Dalaman – Beritahu Valve perkara yang anda rancang untuk disertakan dalam pencapaian ini`,
  zL = `Penerangan Setempat Pelanggan`,
  BL = `Tajuk Paparan Pelanggan`,
  VL = `Paparan Tarikh`,
  HL = `Tarikh Keluaran Dirancang`,
  UL = `Ini ialah tarikh yang anda rancang untuk mengeluarkan kandungan ini kepada pemain. Tarikh ini digunakan untuk menetapkan peringatan pada papan pemuka Steamworks dalaman anda. Sila gunakan zon masa tempatan anda.`,
  WL = `Tarikh Keluaran`,
  GL = `Bilakah pelanggan mula mendapat akses kepada kandungan ini`,
  KL = `Tandakan sebagai telah dikeluarkan sebelum ini`,
  qL = `Ini ialah kandungan yang telah dikeluarkan sebelum ini. Apabila ditandakan, anda boleh menetapkan tarikh pada masa lalu. Apabila diterbitkan, pelanggan tidak akan diberitahu tentang keluarannya. Tidak boleh dinyahtanda jika tarikh berada pada masa lalu.`,
  JL = `Status telah dikeluarkan sebelum ini tidak boleh dibatalkan, melainkan tarikh keluaran ditukar ke masa hadapan terlebih dahulu.`,
  YL = `Perlu Disimpan dan Diterbitkan`,
