  BR = `Bakal Tiba:`,
  VR = `Pautan Tiada`,
  HR = `Pencapaian ini telah dikeluarkan. Pemautan kepada DLC atau acara pelancaran masih boleh dilakukan dan hanya akan mengemas kini paparan tanpa mengubah tarikh keluaran pencapaian.`,
  UR = `Pemautan Selepas Keluaran Pencapaian`,
  WR = `Pencapaian ini telah ditandakan sebagai dikeluarkan kepada pelanggan. Ini boleh digunakan untuk memautkan DLC dan acara pelancaran yang tiada. Apabila diterbitkan, ia hanya akan mengemas kini paparan.`,
  GR = `Tinjauan Pertemuan Industri Pasukan Steam`,
  KR = `Helo %1$s,%2$s Di manakah anda ingin bertemu kami?`,
  qR = `Disenaraikan di bawah ialah acara yang sedang dipertimbangkan untuk dihadiri oleh ahli Pasukan Steam. Jika anda juga bercadang untuk hadir atau tinggal berdekatan dan boleh menyertai pertemuan, sila beritahu kami melalui borang di bawah. Maklumat ini akan membantu kami merancang jadual perjalanan dan acara dengan lebih baik. Jika anda mendaftar untuk acara yang kami rancang untuk hadiri, kami akan memberi keutamaan kepada peserta acara tersebut sebelum menghantar jemputan kepada yang lain.`,
  JR = `Tentang Anda`,
  YR = `Beritahu kami tentang diri anda dan cara terbaik untuk menghubungi anda:`,
  XR = `Alamat E-mel`,
  ZR = `Alamat tiada`,
  QR = `Kemas kini alamat e-mel?`,
  $R = `Ini ditetapkan secara lalai kepada alamat e-mel yang direkodkan dalam akaun rakan kongsi anda. Anda boleh membuat kemas kini, jika anda ingin komunikasi acara dihantar ke alamat yang berbeza.`,
  ez = `Syarikat`,
