  oz = `Tinjauan Persidangan kini ditutup.`,
  sz = `Adakah kami pernah bertemu anda secara bersemuka sebelum ini?`,
  cz = `Tidak, saya tidak pernah bertemu dengan ahli Pasukan Steam secara bersemuka`,
  lz = `Adakah anda selesa menghadiri sesi atau acara yang terutamanya atau sepenuhnya, dalam bahasa Inggeris?`,
  uz = `Ya, saya selesa menggunakan bahasa Inggeris sebagai bahasa utama`,
  dz = `Tidak, saya memerlukan bantuan terjemahan`,
  fz = `Apakah bahasa pilihan anda?`,
  pz = `Ini akan membantu kami menentukan jika jurubahasa diperlukan semasa menganjurkan acara seperti ini`,
  mz = `Tinjauan Meet Steam: %1$s`,
  hz = `Adakah anda mempunyai maklum balas tentang mana-mana sesi Steam yang anda hadiri di ruang sewaan Valve di Convene? Ini ialah tinjauan satu soalan sahaja. Kami ingin memahami jika sesuatu perkara menyerlah dalam fikiran anda berkaitan kandungan, kualiti, masa, lokasi atau topik sesi, sama ada baik atau sebaliknya.`,
  gz = `Acara Terdahulu: (%1$s)`,
  _z = `Penganjur persidangan mahu anda menyatakan jika anda bercadang untuk hadir dan sama ada anda berminat untuk bertemu dengan ahli Steam.`,
