  Az = `Filem permulaan perlu bersaiz 1920x1200px untuk paparan skrin penuh pada Steam Deck. Filem ini perlu dihasilkan dengan mengambil kira bahawa ia akan dipotong kepada 1920x1080px pada kebanyakan paparan dalam mod Big Picture.`,
  jz = `Tempoh filem ini mestilah antara 3-10 saat.`,
  Mz = `Logo permainan anda boleh disertakan, tetapi tiada teks lain atau bahan pemasaran dibenarkan.`,
  Nz = `Transparensi tidak dibenarkan. Anda mungkin perlu melumpuhkan saluran alfa semasa mengeksport.`,
  Pz = `Fail akhir perlu berada dalam format .webm atau .mp4 dan tidak melebihi 50MB. Ia akan dimampatkan kepada saiz fail yang munasabah.`,
  Fz = `Garis Panduan Audio`,
  Iz = `Semua filem permulaan mengandungi audio dan juga video. Audio perlu direka untuk melengkapi output pembesar suara kecil Steam Deck dan tidak terlalu lantang, sehingga mengganggu pengguna semasa permulaan.`,
  Lz = `Fail audio perlu berada dalam format 16-bit 48kHz.`,
