  Vz = `Garis Panduan Imej Pratonton`,
  Hz = `Sila sediakan imej statik bersaiz 1920x1200px daripada filem permulaan anda. Imej ini akan digunakan untuk mewakili filem permulaan anda dalam inventori pengguna.`,
