  Zz = `Kumpulan ini telah dipautkan kepada penerbit dengan nama yang berbeza. Lihat arahan di sebelah kanan.`,
  Qz = `Kumpulan ini dipautkan sebagai pembangun atau penerbit di aplikasi lain, jadi gedung tidak akan memaparkannya sebagai francais. Pautkan kumpulan yang digunakan khusus untuk francais tersebut sahaja.`,
  $z = `Dipautkan sebagai pembangun atau penerbit pada:`,
  eB = `(%1$s lagi)`,
  tB = `Gedung akan memautkan francais ke halaman utamanya sebaik sahaja sekurang-kurangnya dua permainan di gedung memaut kepadanya sebagai francais. DLC, demo dan perisian tidak dikira. Sebelum syarat itu dipenuhi, nama francais akan dipaparkan tanpa pautan.`,
  nB = `Pilih laman utama pencipta`,
