  oB = `* menandakan bahawa laman utama pencipta ini telah dipautkan kepada permainan lain untuk akaun rakan kongsi anda.`,
  sB = `Akaun rakan kongsi untuk permainan ini tidak dapat ditentukan, jadi laman utama pencipta yang dipautkan ke permainan lain anda tidak ditawarkan di sini. Hanya kumpulan komuniti yang anda miliki atau yang anda disenaraikan sebagai pegawai sahaja.`,
  cB = `Tiada laman utama pencipta atau kumpulan komuniti yang tersedia untuk dipautkan. Anda mestilah pemilik atau pegawai bagi kumpulan komuniti tersebut, atau kumpulan itu mestilah sudah dipautkan ke permainan lain untuk akaun rakan kongsi anda.`,
  lB = `Senarai laman utama pencipta tidak dapat dimuatkan. Sila cuba lagi nanti.`,
  uB = `Pautan Laman Utama Pencipta Rosak`,
  dB = `Pautan laman utama pencipta berikut wujud dalam pangkalan data kami, tetapi tidak sepadan sepenuhnya dengan mana-mana nama di atas. Anda boleh mengalih keluarnya dengan selamat.`,
  fB = `Rentetan "%1$s" dipautkan kepada pencipta %2$s`,
