  PB = `Rakaman Permainan - Pengurusan Ikon Garis Masa`,
  FB = `Ikon yang dicipta di sini boleh dirujuk dari dalam permainan anda untuk menandakan detik tertentu pada garis masa rakaman permainan. Steam juga menyediakan set ikon lalai yang boleh anda gunakan. Lihat dokumentasi untuk butiran.`,
