  NK = `Set yang namanya telah diubah suai disenaraikan di sini. Set ini akan dikemas kini.`,
  PK = `Set yang tidak diubah telah disenaraikan di sini. Set ini tidak akan dikemas kini.`,
  FK = `Id set tidak sah: id set mestilah unik`,
