  BK = `Kebenaran tidak sah: pencapaian dan statistik mesti mempunyai kebenaran yang sama`,
  VK = `Integer tidak sah: nilai mestilah integer apabila statistik ialah jenis integer`,
  HK = `Julat kemajuan tidak sah: nilai maksimum mesti lebih besar daripada minimum`,
  UK = `Minimum kemajuan tidak sah: minimum kemajuan pencapaian mesti lebih besar daripada atau sama dengan minimum statistik`,
