  eq = `Pencapaian ini tiada dalam takrif CSV yang dimuat naik, oleh itu penyetempatannya tidak akan dikemaskini. Tambahkannya ke dalam takrif CSV, atau keluarkan rentetan penyetempatan untuknya dari fail ini.`,
